```
def module_path(path: str) ->Tuple[str, Optional[str]]:
    if ":" in path:
        module, qualname = path.rsplit(":", 1)
        return (module, qualname)
    else:
        return (path, None)


def module_path_with_qualname(path: str) ->Tuple[str, str]:
    if ":" in path:
        module, qualname = path.rsplit(":", 1)
        return (module, qualname)
    else:
        return (path, "")


def complain_about_no_traces(args: argparse.Namespace, stderr: IO[str]) ->None:
    module, qualname = args.module_path
    if qualname:
        print(f"No traces found for {module}:{qualname}.", file=stderr)
    else:
        print(f"No traces found for {module}.", file=stderr)


def get_monkeytype_config(path: str) ->Config:
    config = Config.from_path(path)
    if config is None:
        config = Config.default()
    return config


def get_stub(
    args: argparse.Namespace, stdout: IO[str], stderr: IO[str]
) -> Optional[Stub]:
    module, qualname = args.module_path
    thunks = args.config.trace_store().filter(module, qualname, args.limit)
    traces = []
    failed_to_decode_count = 0
    for thunk in thunks:
        try:
            traces.append(thunk.to_trace())
        except MonkeyTypeError as mte:
            if args.verbose:
                print(f"WARNING: Failed decoding trace: {mte}", file=stderr)
            failed_to_decode_count += 1
    if failed_to_decode_count and not args.verbose:
        print(
            f"{failed_to_decode_count} traces failed to decode; use -v for details",
            file=stderr,
        )
    if not traces:
        return None
    rewriter = args.config.type_rewriter()
    if args.disable_type_rewriting:
        rewriter = NoOpRewriter()
    stubs = build_module_stubs_from_traces(
        traces,
        args.config.max_typed_dict_size(),
        existing_annotation_strategy=args.existing_annotation_strategy,
        rewriter=rewriter,
    )
    if args.sample_count:
        display_sample_count(traces, stderr)
    return stubs.get(module, None)


def get_diff(
    args: argparse.Namespace, stdout: IO[str], stderr: IO[str]
) -> Optional[str]:
    args.existing_annotation_strategy = ExistingAnnotationStrategy.REPLICATE
    stub = get_stub(args, stdout, stderr)
    args.existing_annotation_strategy = ExistingAnnotationStrategy.IGNORE
    stub_ignore_anno = get_stub(args, stdout, stderr)
    if stub is None or stub_ignore_anno is None:
        return None
    diff = []
    seq1 = (s + "\n" for s in stub.render().split("\n\n\n"))
    seq2 = (s + "\n" for s in stub_ignore_anno.render().split("\n\n\n"))
    for stub1, stub2 in zip(seq1, seq2):
        if stub1 != stub2:
            stub_diff = "".join(
                difflib.ndiff(
                    stub1.splitlines(keepends=True), stub2.splitlines(keepends=True)
                )
            )
            diff.append(stub_diff[:-1])
    return "\n\n\n".join(diff)


def print_stub_handler(args: argparse.Namespace, stdout: IO[str], stderr:
    IO[str]) ->None:
    stub = get_stub(args, stdout, stderr)
    if stub is None:
        complain_about_no_traces(args, stderr)
        return
    if args.diff:
        diff = get_diff(args, stdout, stderr)
        if diff is not None:
            print(diff, file=stdout)
    else:
        print(stub.render(), file=stdout)


def list_modules_handler(
    args: argparse.Namespace, stdout: IO[str], stderr: IO[str]
) -> None:
    modules = args.config.trace_store().list_modules()
    if modules:
        print("\n".join(modules), file=stdout)
    else:
        print("", file=stdout)


def update_args_from_config(args: argparse.Namespace) ->None:
    if args.config_path:
        args.config = get_monkeytype_config(args.config_path)
    if args.config:
        if not args.existing_annotation_strategy:
            args.existing_annotation_strategy = args.config.existing_annotation_strategy()
        if not args.disable_type_rewriting:
            args.disable_type_rewriting = args.config.disable_type_rewriting()
        if not args.pep_563:
            args.pep_563 = args.config.confine_new_imports_in_type_checking_block()


def main(argv: List[str], stdout: IO[str], stderr: IO[str]) ->int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "-c",
        "--context-manager",
        help="A string that evaluates to a context manager to use when running commands",
    )
    parser.add_argument(
        "-v",
        "--verbose",
        action="store_true",
        help="Print verbose output",
    )
    parser.add_argument(
        "--config-path",
        help="Path to a Python file that defines a monkeytype config",
    )
    subparsers = parser.add_subparsers()

    stub_parser = subparsers.add_parser("stub")
    stub_parser.add_argument(
        "--diff",
        action="store_true",
        help="Show a diff between the current stub and what would be generated",
    )
    stub_parser.add_argument(
        "--ignore-existing-annotations",
        action="store_true",
        help="Ignore existing annotations when generating stubs",
    )
    stub_parser.add_argument(
        "--sample-count",
        action="store_true",
        help="Display the number of traces each stub is based on",
    )
    stub_parser.add_argument(
        "--limit",
        type=int,
        help="Limit the number of traces to process",
    )
    stub_parser.add_argument(
        "--disable-type-rewriting",
        action="store_true",
        help="Disable type rewriting",
    )
    stub_parser.add_argument(
        "--pep-563",
        action="store_true",
        help="Confine new imports in type checking block",
    )
    stub_parser.add_argument(
        "module_path",
        help="Module path to generate stub for",
    )
    stub_parser.set_defaults(handler=print_stub_handler)

    apply_parser = subparsers.add_parser("apply")
    apply_parser.add_argument(
        "--ignore-existing-annotations",
        action="store_true",
        help="Ignore existing annotations when applying stubs",
    )
    apply_parser.add_argument(
        "--pep-563",
        action="store_true",
        help="Confine new imports in type checking block",
    )
    apply_parser.add_argument(
        "module_path",
        help="Module path to apply stub to",
    )
    apply_parser.set_defaults(handler=apply_stub_handler)

    list_modules_parser = subparsers.add_parser("list-modules")
    list_modules_parser.set_defaults(handler=list_modules_handler)

    run_parser = subparsers.add_parser("run")
    run_parser.add_argument(
        "-m",
        action="store_true",
        help="Run module instead of script",
    )
    run_parser.add_argument(
        "script_path",
        help="Script or module to run",
    )
    run_parser.add_argument(
        "script_args",
        nargs=argparse.REMAINDER,
        help="Arguments to pass to the script or module",
    )
    run_parser.set_defaults(handler=run_handler)

    args = parser.parse_args(argv)
    if not hasattr(args, "handler"):
        parser.print_help()
        return 1

    # Set default values for args that might not be set
    if not hasattr(args, "existing_annotation_strategy"):
        args.existing_annotation_strategy = None
    if not hasattr(args, "disable_type_rewriting"):
        args.disable_type_rewriting = False
    if not hasattr(args, "pep_563"):
        args.pep_563 = False
    if not hasattr(args, "sample_count"):
        args.sample_count = False
    if not hasattr(args, "diff"):
        args.diff = False
    if not hasattr(args, "limit"):
        args.limit = None
    if not hasattr(args, "verbose"):
        args.verbose = False

    update_args_from_config(args)

    if args.context_manager:
        import ast
        ctx = ast.literal_eval(args.context_manager)
        with ctx:
            return args.handler(args, stdout, stderr)
    else:
        return args.handler(args, stdout, stderr)
